Thought: Need to find all distinct sender display names and addresses for emails originating from IP 202.205.215.225.
Action: execute[
SELECT DISTINCT SenderDisplayName, SenderFromAddress 
FROM EmailEvents 
WHERE SenderIPv4='202.205.215.225';
]

Thought: Search EmailEvents entries for sender display name containing 'Hailey'.
Action: execute[
SELECT DISTINCT SenderDisplayName, SenderFromAddress, SenderIPv4
FROM EmailEvents
WHERE SenderDisplayName LIKE '%Hailey%';
]

Thought: Search for any sender addresses including 'hailey' to identify the sender related to the incident.
Action: execute[
SELECT DISTINCT SenderDisplayName, SenderFromAddress, SenderIPv4
FROM EmailEvents
WHERE SenderFromAddress LIKE '%hailey%' OR SenderDisplayName LIKE '%Hailey%';
]

Thought: Search EmailEvents for senders with 'johnson' in display name or address to locate 'Hailey Johnson'.
Action: execute[
SELECT DISTINCT SenderDisplayName, SenderFromAddress, SenderIPv4
FROM EmailEvents
WHERE SenderDisplayName LIKE '%Johnson%' OR SenderFromAddress LIKE '%johnson%';
]
